// background.js — фон города, скролл
  // ---------- scrolling background image ----------
  const BG_SRC = "data:image/jpeg;base64,";
  const BG_SRC_2 = "data:image/jpeg;base64,";
  const BG_SRC_3 = "data:image/jpeg;base64,";
  const bgImg = new Image();
  let bgLoaded = false;
  bgImg.onload = () => { bgLoaded = true; };
  bgImg.src = BG_SRC;

  const bgImg2 = new Image();
  let bgLoaded2 = false;
  bgImg2.onload = () => { bgLoaded2 = true; };
  bgImg2.src = BG_SRC_2;

  const bgImg3 = new Image();
  let bgLoaded3 = false;
  bgImg3.onload = () => { bgLoaded3 = true; };
  bgImg3.src = BG_SRC_3;

  const BG_SWITCH_SCORE = 7000;

  let scrollX = 0;
  function drawCityBg(dtScale){
    const nightOn = (typeof nightMode !== 'undefined') && nightMode;
    const ruinsOn = (typeof score !== 'undefined') && score >= BG_SWITCH_SCORE;
    let activeImg, activeReady;
    if(nightOn){
      activeImg = bgImg3; activeReady = bgLoaded3;
    } else if(ruinsOn){
      activeImg = bgImg2; activeReady = bgLoaded2;
    } else {
      activeImg = bgImg; activeReady = bgLoaded;
    }
    if(!activeReady){
      ctx.fillStyle = '#3a1420';
      ctx.fillRect(0,0,W,H);
      return;
    }
    const scaledH = H;
    const scaledW = activeImg.width * (scaledH / activeImg.height);
    scrollX += 1.3 * dtScale;

    const startI = Math.floor(scrollX / scaledW) - 1;
    const endI = Math.ceil((scrollX + W) / scaledW) + 1;
    for(let i = startI; i <= endI; i++){
      const screenX = i*scaledW - scrollX;
      const mirror = (((i % 2) + 2) % 2) === 1;
      ctx.save();
      if(mirror){
        ctx.translate(screenX + scaledW, 0);
        ctx.scale(-1,1);
        ctx.drawImage(activeImg, 0, 0, scaledW, scaledH);
      } else {
        ctx.drawImage(activeImg, screenX, 0, scaledW, scaledH);
      }
      ctx.restore();
    }

    // subtle dark vignette at the bottom so HUD/gameplay reads clearly
    const vg = ctx.createLinearGradient(0, H*0.7, 0, H);
    vg.addColorStop(0, 'rgba(10,5,10,0)');
    vg.addColorStop(1, 'rgba(10,5,10,0.35)');
    ctx.fillStyle = vg;
    ctx.fillRect(0, H*0.7, W, H*0.3);
  }

